import{_ as e,o,c as n,ah as a}from"./chunks/framework.DOp2Lr4v.js";const s="/projects/TonyPi-Pro/en/latest/assets/image3.CdGOKV2K.png",r="data:image/jpeg;base64,",i="data:image/jpeg;base64,",l="/projects/TonyPi-Pro/en/latest/assets/image2.EkaXOLSx.jpeg",d="/projects/TonyPi-Pro/en/latest/assets/image5.QaH79-fM.png",c="/projects/TonyPi-Pro/en/latest/assets/image8.CIR2akEN.png",f=JSON.parse('{"title":"13. Group Control Lessons","description":"","frontmatter":{},"headers":[],"relativePath":"docs/13_group_control_lessons.md","filePath":"docs/13_group_control_lessons.md"}'),h={name:"docs/13_group_control_lessons.md"};function g(p,t,u,A,m,b){return o(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="_13-group-control-lessons" tabindex="-1">13. Group Control Lessons <a class="header-anchor" href="#_13-group-control-lessons" aria-label="Permalink to &quot;13. Group Control Lessons&quot;">​</a></h1><h2 id="_13-1-wireless-handle-control" tabindex="-1">13.1 Wireless Handle Control <a class="header-anchor" href="#_13-1-wireless-handle-control" aria-label="Permalink to &quot;13.1 Wireless Handle Control&quot;">​</a></h2><h3 id="_13-1-1-getting-ready" tabindex="-1">13.1.1 Getting Ready <a class="header-anchor" href="#_13-1-1-getting-ready" aria-label="Permalink to &quot;13.1.1 Getting Ready&quot;">​</a></h3><ul><li><strong>Step 1: Handle Receiver Setup</strong></li></ul><p>(1) Plug the handle receiver into one of USB ports of TonyPi Pro.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The handle receiver must be inserted before the robot is turned on.</p></section><ul><li><strong>Step 2: Battery Installation</strong></li></ul><p>(1) Prepare two AAA batteries. Take off the back cover of the handle and insert them into the battery slot. Please pay attention to the direction of the positive and negative poles.</p><img loading="lazy" height="365" width="977" src="'+s+'" class="common_img"><h3 id="_13-1-2-device-connection" tabindex="-1">13.1.2 Device Connection <a class="header-anchor" href="#_13-1-2-device-connection" aria-label="Permalink to &quot;13.1.2 Device Connection&quot;">​</a></h3><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>If you do not connect the robot within 30 seconds after turning on the handle switch, or if you do not operate the handle within 5 minutes after connecting it, the handle will enter sleep mode. If you need to turn on the handle again, press the <strong>&quot;START&quot;</strong> button.</p></section><ul><li><strong>Connection Process</strong></li></ul><p>(1) Turn on the robot.</p><p>(2) Switch on the handle, and then the two LED lights (red and green) on handle will flash simultaneously.</p><p>(3) Wait for a few seconds, pair the handle with the robot. After pairing, the green light will keep on.</p><h3 id="_13-1-3-mode-introduction" tabindex="-1">13.1.3 Mode Introduction <a class="header-anchor" href="#_13-1-3-mode-introduction" aria-label="Permalink to &quot;13.1.3 Mode Introduction&quot;">​</a></h3><p>The handle has two modes: single green light mode and green and red lights mode (The red and green lights will turn on simultaneously).</p><ul><li><strong>Single green light mode</strong></li></ul><p>All the buttons can be used.</p><ul><li><strong>Red and green lights mode</strong></li></ul><p>The four buttons <strong>&quot;↑&quot;</strong>、<strong>&quot;↓&quot;</strong>、<strong>&quot;←&quot;</strong>、<strong>&quot;→&quot;</strong> are locked and can not be used. The function of the remaining buttons is the same as that of the green and red lights mode.</p><ul><li><strong>Mode Switching Method</strong></li></ul><p>Press <strong>&quot;MODE&quot;</strong> button to switch the mode from the green light mode to another mode, and press the button again to switch to the green light mode.</p><h3 id="_13-1-4-button-instruction" tabindex="-1">13.1.4 Button Instruction <a class="header-anchor" href="#_13-1-4-button-instruction" aria-label="Permalink to &quot;13.1.4 Button Instruction&quot;">​</a></h3><p>The corresponding relation between the button and the action is as the following table:</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Button</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;">START</td><td style="text-align:center;">The robot returns to the initial posture</td></tr><tr><td style="text-align:center;">L1</td><td style="text-align:center;">Right tilt and lift the left foot</td></tr><tr><td style="text-align:center;">R1</td><td style="text-align:center;">Left tilt and lift right foot</td></tr><tr><td style="text-align:center;"><strong>↑</strong></td><td style="text-align:center;">Move forward</td></tr><tr><td style="text-align:center;"><strong>↓</strong></td><td style="text-align:center;">Move backward</td></tr><tr><td style="text-align:center;"><strong>←</strong></td><td style="text-align:center;">Move to left</td></tr><tr><td style="text-align:center;"><strong>→</strong></td><td style="text-align:center;">Move to right</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="27" width="30" src="'+r+'"></td><td style="text-align:center;">Wave</td></tr><tr><td style="text-align:center;"><strong>×</strong></td><td style="text-align:center;">Bow</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="26" width="26" src="'+i+'"></td><td style="text-align:center;">Twist waist</td></tr><tr><td style="text-align:center;"><strong>○</strong></td><td style="text-align:center;">Right-footed shot</td></tr><tr><td style="text-align:center;">Push up the left slider</td><td style="text-align:center;">Move forward</td></tr><tr><td style="text-align:center;">Push down the left slider</td><td style="text-align:center;">Move backward</td></tr><tr><td style="text-align:center;">Push the left slider to left</td><td style="text-align:center;">Move to left</td></tr><tr><td style="text-align:center;">Push the left slider to right</td><td style="text-align:center;">Move to right</td></tr><tr><td style="text-align:center;">Push up the right slider</td><td style="text-align:center;">Wave</td></tr><tr><td style="text-align:center;">Push down the right slider</td><td style="text-align:center;">Bow</td></tr><tr><td style="text-align:center;">Push the right slider to left</td><td style="text-align:center;">Twist waist</td></tr><tr><td style="text-align:center;">Push the right slider to right</td><td style="text-align:center;">Right-footed shot</td></tr></tbody></table><h2 id="_13-2-group-control" tabindex="-1">13.2 Group Control <a class="header-anchor" href="#_13-2-group-control" aria-label="Permalink to &quot;13.2 Group Control&quot;">​</a></h2><h3 id="_13-2-1-getting-ready" tabindex="-1">13.2.1 Getting Ready <a class="header-anchor" href="#_13-2-1-getting-ready" aria-label="Permalink to &quot;13.2.1 Getting Ready&quot;">​</a></h3><ul><li><strong>Equipment Preparation</strong></li></ul><p>(1) Prepare at least two or more TonyPi Pro (this lesson takes two robots as example).</p><p>(2) Set development environment. Please refer to <a href="./3_remote_desktop_tool_installation_and_connection.html#3-remote-desktop-tool-installation-and-connection"><strong>3.1 Remote Tool Installation and Connection</strong></a> and download and install VNC remote connection tool.</p><h3 id="_13-2-2-working-principle" tabindex="-1">13.2.2 Working Principle <a class="header-anchor" href="#_13-2-2-working-principle" aria-label="Permalink to &quot;13.2.2 Working Principle&quot;">​</a></h3><p>Through configuring the master robot and the slave robot in the same network, the master sends the commands to the group sending program to achieve the effect of controlling the slave.</p><h3 id="_13-2-3-operation-steps" tabindex="-1">13.2.3 Operation Steps <a class="header-anchor" href="#_13-2-3-operation-steps" aria-label="Permalink to &quot;13.2.3 Operation Steps&quot;">​</a></h3><ul><li><strong>Configure the Master Robot</strong></li></ul><p>(1) Firstly, choose a robot as the master. After booting up the robot, connect it to the remote desktop. Take the robot whose hotspot is <strong>&quot;HW-F199CEEE&quot;</strong> as example.</p><img loading="lazy" height="341" width="428" src="'+l+'" class="common_img"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>Please remember the name of the connected hotspot and it will be used in the following steps.</p></section><p>(2) Open the terminal and enter the WiFi configuration directory. Then enter command and press <strong>&quot;Enter&quot;</strong>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd hiwonder-toolbox</span></span></code></pre></div><p>(3) Open WiFi configuration file via vi editor, and then enter command and press <strong>&quot;Enter&quot;</strong>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo vim wifi_conf.py</span></span></code></pre></div><p>(4) Press <strong>&quot;i&quot;</strong> on keyboard to enter the editing mode.</p><img loading="lazy" height="627" width="743" src="'+d+'" class="common_img"><p>(5) Modify the WiFi password of the master to <strong>&quot;123456789&quot;</strong> and then uncomment it.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The password cannot be less than 8 digits.</p></section><p>(6) After modification, press <strong>&quot;Esc&quot;</strong> and then enter <strong>&quot;:wq&quot;</strong>.</p><p>(7) Input command to restart the device. This step cannot be skipped!</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo reboot</span></span></code></pre></div><p>(8) Open the terminal and enter the WiFi configuration directory. Then enter command and press <strong>&quot;Enter&quot;</strong>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd hiwonder-toolbox</span></span></code></pre></div><p>(9) Open WiFi configuration file via vi editor, and then enter command and press <strong>&quot;Enter&quot;</strong>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo vim wifi_conf.py</span></span></code></pre></div><p>(10) Press <strong>&quot;i&quot;</strong> on keyboard to enter the editing mode.</p><p>(11) The hotspot name and password of the slave are set to be the same as the hotspot name and password of the master (this lesson takes <strong>&quot;ID: HW-F119CEEE&quot;</strong> as example). Then uncomment the code.</p><img loading="lazy" height="214" width="730" src="'+c+'" class="common_img"><p>(12) After modification, press <strong>&quot;Esc&quot;</strong> and then enter <strong>&quot;:wq&quot;</strong> to save modification and exit it.</p><p>(13) Enter command to reboot the robot (this step cannot be skipped!).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo reboot</span></span></code></pre></div><ul><li><strong>Group Control Operation</strong></li></ul><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>When controlling the group of robots, the slave can be turned on after the master robot is booted up successfully.</p></section><p>(1) Place the master robot and the slave robot on a clean and flat ground, and keep a certain distance from each other.</p><p>(2) Plug the handle receiver into the USB port of the master, and then switch on the handle to control the group of robots.</p><h3 id="_13-2-4-project-outcome" tabindex="-1">13.2.4 Project Outcome <a class="header-anchor" href="#_13-2-4-project-outcome" aria-label="Permalink to &quot;13.2.4 Project Outcome&quot;">​</a></h3><p>After the program is started, the master and the slave will perform the same action group at the same time.</p>',65)])])}const w=e(h,[["render",g]]);export{f as __pageData,w as default};
